#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    long long x = *(const long long*)a;
    long long y = *(const long long*)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    long long *a = (long long*)malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) {
        scanf("%lld", &a[i]);
    }

    long long *gain = (long long*)malloc(N * sizeof(long long));
    long long S_base = 0;
    long long sum_a = 0;

    for (int i = 0; i < N; i++) {
        long long b;
        scanf("%lld", &b);
        long long base = (a[i] > b) ? (a[i] - b) : 0;
        S_base += base;
        long long g = (a[i] < b) ? a[i] : b;
        gain[i] = g;
        sum_a += a[i];
    }

    if (K >= N - 1) {
        printf("%lld\n", sum_a);
        free(a);
        free(gain);
        return 0;
    }

    long long *g = (long long*)malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) g[i] = gain[i];
    qsort(g, N, sizeof(long long), cmp);

    long long *pref = (long long*)malloc((N + 1) * sizeof(long long));
    pref[0] = 0;
    for (int i = 1; i <= N; i++) {
        pref[i] = pref[i-1] + g[i-1];
    }

    long long total_top_K = (K > 0) ? pref[K] : 0;
    long long answer = 0;

    for (int i = 0; i < N; i++) {
        long long v = gain[i];
        long long topK_excl;
        if (K == 0) {
            topK_excl = 0;
        } else {
            if (v >= g[K-1]) {
                topK_excl = total_top_K - v + g[K];
            } else {
                topK_excl = total_top_K;
            }
        }
        long long V = S_base + v + topK_excl;
        if (V > answer) answer = V;
    }

    printf("%lld\n", answer);

    free(a);
    free(gain);
    free(g);
    free(pref);
    return 0;
}
