#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

int cmp(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    ll *a = (ll*)malloc(N * sizeof(ll));
    ll *b = (ll*)malloc(N * sizeof(ll));
    ll *v = (ll*)malloc(N * sizeof(ll));

    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &b[i]);

    ll ans = 0;
    for (int i = 0; i < N; i++) {
        if (a[i] > b[i]) {
            ans += a[i] - b[i];
            v[i] = b[i];
        } else {
            v[i] = a[i];
        }
    }

    qsort(v, N, sizeof(ll), cmp);

    int take = K + 1;
    if (take > N) take = N;

    for (int i = 0; i < take; i++) {
        ans += v[i];
    }

    printf("%lld\n", ans);

    free(a);
    free(b);
    free(v);

    return 0;
}
